function decodeHtml(value) {
  return String(value || '')
    .replace(/&#(\d+);/g, (_, number) => String.fromCodePoint(Number(number)))
    .replace(/&#x([0-9a-f]+);/gi, (_, number) => String.fromCodePoint(parseInt(number, 16)))
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>');
}

function htmlToText(value) {
  return decodeHtml(String(value || '')
    .replace(/<script\b[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style\b[\s\S]*?<\/style>/gi, ' ')
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/<[^>]+>/g, ' '))
    .replace(/\s+/g, ' ')
    .trim();
}

function readAttribute(tag, name) {
  const match = String(tag).match(new RegExp(`\\b${name}\\s*=\\s*["']([^"']*)["']`, 'i'));
  return match ? decodeHtml(match[1]) : '';
}

function readHook(card, name) {
  const pattern = new RegExp(`<([a-z0-9]+)\\b[^>]*data-hook=["']${name}["'][^>]*>([\\s\\S]*?)<\\/\\1>`, 'i');
  const match = card.match(pattern);
  return match ? htmlToText(match[2]) : '';
}

function readReviewBody(card) {
  const start = card.match(/<([a-z0-9]+)\b[^>]*data-hook=["']review-body["'][^>]*>/i);
  if (!start || start.index === undefined) return '';
  const bodyStart = start.index + start[0].length;
  const tail = card.slice(bodyStart);
  const boundaries = [
    tail.search(/<div\b[^>]*class=["'][^"']*\bcr-vote-action-bar\b/i),
    tail.search(/<[^>]+data-hook=["']review-voting-widget["']/i),
  ].filter((index) => index >= 0);
  const bodyHtml = tail.slice(0, boundaries.length ? Math.min(...boundaries) : tail.length);
  return htmlToText(bodyHtml).replace(/The media could not be loaded\.\s*/gi, '').trim();
}

function parseAmazonReviewPage(html, options = {}) {
  const domain = String(options.domain || 'www.amazon.com');
  const source = String(html || '');
  const starts = [];
  const cardStart = /<(?:li|div|article)\b[^>]*data-hook=["']review["'][^>]*>/gi;
  let match;
  while ((match = cardStart.exec(source))) starts.push({ at: match.index, tag: match[0] });

  const reviews = [];
  for (let index = 0; index < starts.length; index += 1) {
    const card = source.slice(starts[index].at, index + 1 < starts.length ? starts[index + 1].at : source.length);
    let reviewId = readAttribute(starts[index].tag, 'id') || readAttribute(starts[index].tag, 'data-review-id');
    let reviewUrl = '';
    const urlMatch = card.match(/href=["']([^"']*(?:(?:\/gp)?\/customer-reviews\/[A-Z0-9]+|\/portal\/customer-reviews\/srp\/-\/[A-Z0-9]+)[^"']*)["']/i);
    if (urlMatch) reviewUrl = decodeHtml(urlMatch[1]);
    if (!reviewId && reviewUrl) {
      const idMatch = reviewUrl.match(/(?:customer-reviews\/|customer-reviews\/srp\/-\/)([A-Z0-9]+)/i);
      if (idMatch) reviewId = idMatch[1];
    }
    reviewId = String(reviewId || '').trim().toUpperCase();

    let ratingText = readHook(card, 'review-star-rating') || readHook(card, 'cmps-review-star-rating');
    if (!ratingText) {
      const ratingAttribute = card.match(/(?:aria-label|title)=["']([^"']*(?:out of 5|de 5)[^"']*)["']/i);
      ratingText = ratingAttribute ? decodeHtml(ratingAttribute[1]) : '';
    }
    let ratingMatch = ratingText.match(/([0-5](?:[\.,]\d)?)/);
    if (!ratingMatch) ratingMatch = htmlToText(card.slice(0, 1800)).match(/([0-5](?:[\.,]\d)?)\s*(?:out of 5|de 5)/i);
    const rating = ratingMatch ? Number(ratingMatch[1].replace(',', '.')) : NaN;

    if (reviewUrl.startsWith('/')) reviewUrl = `https://${domain}${reviewUrl.split('?')[0]}`;
    else if (reviewUrl) reviewUrl = reviewUrl.split('?')[0];

    const title = readHook(card, 'review-title').replace(/^[0-5](?:[\.,]\d)?\s*out of 5 stars\s*/i, '').trim();
    reviews.push({
      review_id: reviewId,
      rating,
      title,
      body: readReviewBody(card),
      review_date: readHook(card, 'review-date'),
      verified_purchase: /data-hook=["']avp-badge["']/i.test(card) || /Verified Purchase|Compra verificada/i.test(htmlToText(card)),
      variant: readHook(card, 'format-strip'),
      review_url: reviewUrl,
    });
  }

  return { cards: starts.length, reviews };
}

function filterReviews(parsedPage, targetRating, sinceDate) {
  const seen = new Set();
  const reviews = [];
  let rejectedRatingMismatch = 0;
  let rejectedOutsideDate = 0;
  const cutoff = sinceDate ? Date.parse(sinceDate+'T00:00:00Z') : null;

  for (const review of parsedPage.reviews || []) {
    const validId = /^[A-Z0-9]{8,32}$/.test(review.review_id);
    const validRating = Number.isFinite(review.rating) && review.rating === Number(targetRating);
    const hasText = Boolean(review.title || review.body);
    const dateMatch = String(review.review_date || '').match(/\bon\s+(.+)$/i);
    const reviewTime = Date.parse(dateMatch ? dateMatch[1] : String(review.review_date || ''));
    const withinDate = cutoff === null || (Number.isFinite(reviewTime) && reviewTime >= cutoff);
    if (!withinDate) rejectedOutsideDate += 1;
    if (Number.isFinite(review.rating) && !validRating) rejectedRatingMismatch += 1;
    if (!validId || !validRating || !hasText || !withinDate || seen.has(review.review_id)) continue;
    seen.add(review.review_id);
    reviews.push(review);
  }

  return { reviews, rejected_rating_mismatch: rejectedRatingMismatch, rejected_outside_date: rejectedOutsideDate };
}


const c=$('Config - HTML Ingest Guardrails').first().json,x=$('Code - Normalize Raw HTML').item.json;
let status=x.capture_status==='CAPTURED'?'SUCCEEDED':'FAILED',error=x.capture_error||null,complete=false,rejected_rating_mismatch=0,rejected_outside_date=0,totalCards=0;
const reviews=[],seen=new Set(),parseErrors=[];
for(const page of Array.isArray(x.raw_pages)?x.raw_pages:[]){
  try{
    const parsed=parseAmazonReviewPage(page.html,{domain:c.domain});
    const filtered=filterReviews(parsed,x.star_filter,x.since_date);
    totalCards+=parsed.cards;
    rejected_rating_mismatch+=filtered.rejected_rating_mismatch;
    rejected_outside_date+=filtered.rejected_outside_date;
    for(const review of filtered.reviews){if(!seen.has(review.review_id)){seen.add(review.review_id);reviews.push(review)}}
  }catch(err){parseErrors.push('page '+page.page_number+': '+String(err.message||err))}
}
if(x.capture_status==='CAPTURED'){
  complete=parseErrors.length===0&&rejected_rating_mismatch===0&&totalCards>0&&reviews.length>0;
  if(parseErrors.length){status='PARTIAL';error=parseErrors.join('; ')}
  else if(totalCards===0){status='FAILED';error='No review cards found; refusing to treat sign-in, robot, CAPTCHA, or empty pages as a successful collection'}
  else if(reviews.length===0&&rejected_outside_date===totalCards){status='SUCCEEDED';complete=true;error=null}
  else if(reviews.length===0){status='PARTIAL';error=rejected_rating_mismatch>0?'Page filter mismatch: all '+rejected_rating_mismatch+' cards had ratings other than '+x.star_filter:'Review cards found but parser produced no valid target-rating reviews'}
  else if(rejected_rating_mismatch>0){status='PARTIAL';error='Rejected rating mismatches: '+rejected_rating_mismatch}
}
const requested=(Array.isArray(x.raw_pages)?x.raw_pages:[]).length;
const stop_reason=totalCards===0&&requested?'no_review_cards':'requested_pages_processed';
return [{json:{job_id:x.job_id,run_id:x.run_id,marketplace:x.marketplace,asin:x.asin,star_filter:x.star_filter,
client_id:x.client_id,brand_id:x.brand_id,brand_name:x.brand_name,audit_frequency_hours:x.audit_frequency_hours,
