browser_session_summary:x.browser_session_summary,pages:requested,stop_reason,error_detail:error?String(error).slice(0,1000):null,
rejected_rating_mismatch,rejected_outside_date,review_cards_found:totalCards,reviews}}];

const c=$('Config - HTML Ingest Guardrails').first().json,r=$json.review||{};
return {json:{...$json,policy_version:c.policy_version,prompt_version:c.prompt_version,model_name:c.ai_model,
gate:c.confidence_gate,review:r,prompt:JSON.stringify({task:'Conservatively classify this Amazon product review. Negative opinions are allowed.',
categories:["SELLER_CUSTOMER_SERVICE_ONLY","ORDER_OR_RETURN_ONLY","SHIPPING_PACKAGING_ONLY","PRODUCT_CONDITION_OR_DELIVERY_DAMAGE_ONLY","SHIPPING_COST_OR_SPEED_ONLY","INDIVIDUAL_PRICE_OR_AVAILABILITY","UNSUPPORTED_LANGUAGE","SPAM_REPETITIVE_OR_GIBBERISH","PRIVATE_INFORMATION","PROFANITY_HARASSMENT_OR_THREAT","HATE_SPEECH","SEXUALLY_EXPLICIT_CONTENT","EXTERNAL_LINK","ADVERTISEMENT_OR_PROMOTION","CONFLICT_OF_INTEREST","COMPENSATED_OR_INCENTIVIZED_REVIEW","PLAGIARISM_INFRINGEMENT_OR_IMPERSONATION","ILLEGAL_ACTIVITY_OR_DANGEROUS_MISUSE","PROHIBITED_MEDICAL_CLAIM","WRONG_PRODUCT_OR_VARIATION","SUSPECTED_REVIEW_ABUSE","NO_POLICY_VIOLATION_IDENTIFIED"],review:r})}};

const s=$('Code - Prepare AI Review').item.json,x=$json||{};
function J(v){const a=[v?.output_text,v?.text,v?.response,v?.output?.[0]?.content?.[0]?.text,v?.choices?.[0]?.message?.content];
for(const z of a){if(z&&typeof z==='object'&&z.decision)return z;if(typeof z!=='string')continue;
const q=z.trim().replace(/^\x60\x60\x60(?:json)?\s*/i,'').replace(/\s*\x60\x60\x60$/,'');
try{return JSON.parse(q)}catch{}const m=q.match(/\{[\s\S]*\}/);if(m)try{return JSON.parse(m[0])}catch{}}return null}
